        !byte $00                       ; Damage letter G: gun_jammed toggles.
        !byte $ff
        !byte $00                       ; Score digit 10000 (one decimal digit per byte).
        !byte $00                       ; Score digit 1000.
        !byte $00                       ; Score digit 100.
        !byte $03                       ; Score digit 10. add_score adds the points here.
        !byte $00                       ; Score digit 1. It stays 0.
        !byte $01                       ; Sprite enable bits for $d015.
        !byte $0f                       ; Sprite 0 (plane) X / 2. Start of the 8 sprite X entries.
        !byte $5b                       ; Sprite 1 (enemy plane, boat, vehicle) X / 2.
        !byte $68                       ; Sprite 2 (bomb) X / 2.
        !byte $38                       ; Sprite 3 (bullet) X / 2.
        !byte $11,$b6                   ; Sprites 4-5 (flak shells) X / 2.
        !byte $1e                       ; Sprite 6 (plane shadow) X / 2: the ground position of the plane.
        !byte $5b                       ; Sprite 7 (enemy shadow or special target) X / 2.
        !byte $c5                       ; Sprite 0 Y = shadow_y - altitude. Start of the 8 sprite Y entries.
        !byte $a0                       ; Sprite 1 Y.
        !byte $b6                       ; Sprite 2 Y.
        !byte $67                       ; Sprite 3 Y.
        !byte $8f                       ; Sprite 4 Y.
        !byte $99                       ; Sprite 5 Y.
        !byte $b4                       ; Sprite 6 Y: the ground position of the plane.
        !byte $bf                       ; Sprite 7 Y.
; $40d4-$40d9: no code reads or writes these bytes.
        !byte $80,$00,$00,$00,$00,$00
        !byte $29                       ; Plane altitude (ALT on the status line).
        !byte $00
        !byte $1e                       ; Sprite 0 X bits 0-7 for $d000, built by sprites_x_double.
        !byte $b6                       ; Sprite 1 X bits 0-7 for $d002, built by sprites_x_double.
        !byte $d0                       ; Sprite 2 X bits 0-7 for $d004, built by sprites_x_double.
        !byte $70                       ; Sprite 3 X bits 0-7 for $d006, built by sprites_x_double.
        !byte $22                       ; Sprite 4 X bits 0-7 for $d008, built by sprites_x_double.
        !byte $6c                       ; Sprite 5 X bits 0-7 for $d00a, built by sprites_x_double.
        !byte $3c                       ; Sprite 6 X bits 0-7 for $d00c, built by sprites_x_double.
        !byte $b6                       ; Sprite 7 X bits 0-7 for $d00e, built by sprites_x_double.
        !byte $a6                       ; Sprite 0 pointer, copied to $07f8 and $0bf8.
        !byte $e1                       ; Sprite 1 pointer, copied to $07f9 and $0bf9.
        !byte $ef                       ; Sprite 2 pointer, copied to $07fa and $0bfa.
        !byte $ee                       ; Sprite 3 pointer, copied to $07fb and $0bfb.
        !byte $f5                       ; Sprite 4 pointer, copied to $07fc and $0bfc.
        !byte $fb                       ; Sprite 5 pointer, copied to $07fd and $0bfd.
        !byte $e7                       ; Sprite 6 pointer, copied to $07fe and $0bfe.
        !byte $e7                       ; Sprite 7 pointer, copied to $07ff and $0bff.
        !byte $01                       ; Sprite 0 colour for $d027.
        !byte $07                       ; Sprite 1 colour for $d028.
        !byte $00                       ; Sprite 2 colour for $d029.
        !byte $01                       ; Sprite 3 colour for $d02a.
        !byte $02                       ; Sprite 4 colour for $d02b.
        !byte $00                       ; Sprite 5 colour for $d02c.
}}
}
